SELECT th.TSF_NO, th.STATUS, th.TSF_TYPE,     th.FROM_LOC, th.FROM_LOC_TYPE,     CASE th.FROM_LOC_TYPE WHEN 'S' THEN stf.STORE_NAME WHEN 'W' THEN whf.WH_NAME END AS from_loc_name,     th.TO_LOC, th.TO_LOC_TYPE,     CASE th.TO_LOC_TYPE WHEN 'S' THEN stt.STORE_NAME WHEN 'W' THEN wht.WH_NAME END AS to_loc_name,     th.CREATE_DATE, th.APPROVAL_DATE, th.EXP_DC_DATE, th.DELIVERY_DATE,     td.ITEM, im.ITEM_DESC, im.DEPT, d.DEPT_NAME,     td.TSF_QTY, td.SHIP_QTY, td.RECEIVED_QTY,     (td.SHIP_QTY - td.RECEIVED_QTY) AS outstanding_qty, td.TSF_COST FROM MFCS_RDS.RDS_WV_TSFHEAD th     JOIN MFCS_RDS.RDS_WV_TSFDETAIL td ON th.TSF_NO = td.TSF_NO     JOIN MFCS_RDS.RDS_WV_ITEM_MASTER im ON td.ITEM = im.ITEM     LEFT JOIN MFCS_RDS.RDS_WV_DEPS d ON im.DEPT = d.DEPT     LEFT JOIN MFCS_RDS.RDS_WV_STORE stf ON th.FROM_LOC = stf.STORE AND th.FROM_LOC_TYPE = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH   whf ON th.FROM_LOC = whf.WH   AND th.FROM_LOC_TYPE = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_STORE stt ON th.TO_LOC   = stt.STORE AND th.TO_LOC_TYPE   = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH   wht ON th.TO_LOC   = wht.WH   AND th.TO_LOC_TYPE   = 'W' WHERE 1=1 AND th.STATUS NOT IN ('C','D') ORDER BY th.CREATE_DATE DESC, th.TSF_NO</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>TSF_NO</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>STATUS</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>TSF_TYPE</ds:name><ds:datatype>varchar(6)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>FROM_LOC</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>FROM_LOC_TYPE</ds:name><ds:datatype>varchar(1)</ds:datatype></ds:column><ds:column><ds:name>FROM_LOC_NAME</ds:name><ds:datatype>varchar(150)</ds:datatype></ds:column><ds:column><ds:name>TO_LOC</ds:name><ds:datatype>number</ds:datatype></ds: